617961102.en:
Peak engineering
```
#![feature(allocator_api)]

use std::{alloc::Allocator, marker::PhantomData, mem::MaybeUninit};

#[derive(Clone, Copy, Default)]
pub struct NoAlloc<'a>(PhantomData<&'a ()>);

unsafe impl Allocator for NoAlloc<'_> {
    fn allocate(
        &self,
        _: std::alloc::Layout,
    ) -> Result<std::ptr::NonNull<[u8]>, std::alloc::AllocError> {
        Err(std::alloc::AllocError)
    }

    unsafe fn deallocate(&self, _: std::ptr::NonNull<u8>, _: std::alloc::Layout) {}
}

pub type Own<'a, T> = Box<T, NoAlloc<'a>>;
pub fn vec_take<T, A: Allocator>(x: &mut Vec<T, A>) -> Own<'_, [T]> {
    let len = x.len();
    unsafe {
        x.set_len(0);
        Own::from_raw_in(
            std::ptr::slice_from_raw_parts_mut(x.as_mut_ptr(), len),
            NoAlloc::default(),
        )
    }
}
pub fn option_as_owned<T>(x: Own<Option<T>>) -> Option<Own<T>> {
    unsafe {
        match Own::leak(x) {
            Some(x) => Some(Own::from_raw_in(x, NoAlloc::default())),
            None => None,
        }
    }
}
pub fn maybeuninit_write_owned<T>(x: &mut MaybeUninit<T>, val: T) -> Own<'_, T> {
    unsafe { Own::from_raw_in(x.write(val), NoAlloc::default()) }
}
fn own_slice_split_first<T>(slice: Own<[T]>) -> (Option<Own<T>>, Own<[T]>) {
    unsafe {
        match Box::leak(slice) {
            e @ [] => (None, Own::from_raw_in(e, NoAlloc::default())),
            [first, rest @ ..] => (
                Some(Own::from_raw_in(first, NoAlloc::default())),
                Own::from_raw_in(rest, NoAlloc::default()),
            ),
        }
    }
}

fn main() {
    let mut a = MaybeUninit::uninit();
    let mut x: Own<Vec<_>> = maybeuninit_write_owned(&mut a, Vec::from_iter(1..100));
    let mut items: Own<[_]> = vec_take(&mut x);
    while let (Some(first), rest) = own_slice_split_first(items) {
        dbg!(first);
        items = rest;
    }
}
```

