574189439.en:
```rs
struct ReentrantMutex {
    // address of &Owner currently owning this mutex
    owner: AtomicUsize,
    // number of times locked by the owner
    lock_count: UnsafeCell<usize>,
}

struct Owner { _not_zst: u8 }
impl !Sync for Owner {}

impl ReentrantMutex {
    fn try_lock<'a>(&'a self, own: &'a Owner) -> Option<MutexGuard<'a>> {
        let key = (own as *const Owner).addr();
        let success = match self.owner.compare_exchange(0, key, Acquire, Relaxed) {
            Ok(_) => true,
            Err(prev) => prev == key,
        };
        if success {
            unsafe { *self.lock_count.get() += 1 };
            Some(MutexGuard(self))
        } else {
            None
        }
    }
}
```

