unsafe fn g(x: i32) -> i32 { std::hint::assert_unchecked(x != 0); x }

fn roundtrip(f: unsafe fn()) -> unsafe fn() {
  unsafe {
    let ptr = f as *const u8;
    let ptr: *const u8 = ptr::with_exposed_provenance(ptr.expose_provenance());
    transmute(ptr)
  }
}

fn main() {
  let fptr = roundtrip(f as unsafe fn(i32) -> i32);
  let gptr = roundtrip(g as unsafe fn(i32) -> i32);
  if std::ptr::fn_addr_eq(fptr, gptr) {
